import sys
import os
import json
import xml.etree.ElementTree as ET
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64

def encrypt(text: str) -> str:
    passphrase = os.getenv("CONFIG_PASSPHRASE")
    if not passphrase:
        sys.stderr.write("CONFIG_PASSPHRASE is not set\n")
        sys.exit(1)
    cipher = AES.new(passphrase.encode(), AES.MODE_EAX)
    ciphertext, tag = cipher.encrypt_and_digest(text.encode())
    return base64.b64encode(ciphertext + tag).decode()

def decrypt(encrypted_text: str) -> str:
    passphrase = os.getenv("CONFIG_PASSPHRASE")
    if not passphrase:
        sys.stderr.write("CONFIG_PASSPHRASE is not set\n")
        sys.exit(1)
    encrypted_data = base64.b64decode(encrypted_text.encode())
    cipher = AES.new(passphrase.encode(), AES.MODE_EAX, ciphertext=encrypted_data[:16], nonce=encrypted_data[16:32])
    plaintext = unpad(cipher.decrypt(encrypted_data[32:]), AES.block_size)
    return plaintext.decode()

def render():
    params = json.loads(sys.stdin.read())
    tree = ET.parse("config.xml")
    root = tree.getroot()
    result = {}
    for setting in root.findall("setting"):
        name = setting.get("name")
        if setting.get("encrypted") == "yes":
            encrypted_text = setting.text
            decrypted_text = decrypt(encrypted_text)
            if decrypted_text == "{{expr}}":
                expr = decrypted_text[7:-1]
                result[name] = eval(expr, {"__builtins__": None}, params)
            else:
                result[name] = decrypted_text
        else:
            if setting.text == "{{expr}}":
                expr = setting.text[7:-1]
                result[name] = eval(expr, {"__builtins__": None}, params)
            else:
                result[name] = setting.text
    sorted_result = {k: result[k] for k in sorted(result.keys())}
    print(json.dumps(sorted_result))

if __name__ == "__main__":
    if len(sys.argv) == 2 and sys.argv[1] == "encrypt":
        sys.stdout.write(encrypt(sys.stdin.read()))
    elif len(sys.argv) == 3 and sys.argv[1] == "render":
        render()
    else:
        sys.stderr.write("Usage: python confgen.py encrypt or python confgen.py render config.xml params.json\n")
        sys.exit(1)

import argparse
import base64
import json
import os
import sys
from cryptography.fernet import Fernet
from xml.etree import ElementTree as ET

def encrypt_text(text: str, passphrase: str) -> str:
    key = passphrase.encode()
    fernet = Fernet(base64.urlsafe_b64encode(key))
    return fernet.encrypt(text.encode()).decode()

def decrypt_text(encrypted_text: str, passphrase: str) -> str:
    key = passphrase.encode()
    fernet = Fernet(base64.urlsafe_b64b64encode(key))
    return fernet.decrypt(encrypted_text.encode()).decode()

def process_encrypt():
    if not sys.stdin.isatty():
        text = sys.stdin.read()
        passphrase = os.getenv('CONFIG_PASSPHRASE')
        if not passphrase:
            sys.stderr.write("Error: CONFIG_PASSPHRASE environment variable not set.\n")
            sys.exit(1)
        encrypted = encrypt_text(text, passphrase)
        print(encrypted)

def process_render():
    config_xml = sys.argv[1]
    tree = ET.parse(config_xml)
    root = tree.getroot()
    settings = {}
    passphrase = os.getenv('CONFIG_PASSPHRASE')
    if not passphrase:
        sys.stderr.write("Error: CONFIG_PASSPHRASE environment variable not set.\n")
        sys.exit(1)

    for setting in root.findall('setting'):
        name = setting.attrib.get('name')
        if name is None:
            continue
        encrypted_text = setting.text.strip()
        if not encrypted_text:
            continue
        try:
            decrypted_text = decrypt_text(encrypted_text, passphrase)
            if decrypted_text == '{{expr}}':
                expr = decrypted_text[6:-1].strip()
                try:
                    value = eval(expr)
                except:
                    value = decrypted_text
            else:
                value = decrypted_text
            settings[name] = value
        except Exception as e:
            sys.stderr.write(f"Error decrypting setting {name}: {e}\n")
            sys.exit(1)

    print(json.dumps(settings))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('action', choices=['encrypt', 'render'])
    if parser.parse_args().action == 'render':
        parser.add_argument('config_file')
        args = parser.parse_args()
        process_render()
    else:
        process_encrypt()

if __name__ == "__main__":
    main()
